/**
     * Adds an ignored field with missing value, that will be retrieved from the source on a subsequent parsing pass.
     */
    public final void addIgnoredFieldMissingValue(IgnoredSourceFieldMapper.NameValue ignoredFieldWithNoSource) {
        if (canAddIgnoredField()) {
            if (arrayFieldMissingValue != null) {
                // The field is within an array, store the full array instead.
                ignoredFieldsMissingValues.add(arrayFieldMissingValue);
                recordedSource = true;
            } else {
                assert ignoredFieldWithNoSource != null;
                assert ignoredFieldWithNoSource.value() == null;
                ignoredFieldsMissingValues.add(ignoredFieldWithNoSource);
            }
        }
    }

private void addIgnoredSourceMissingValues(DocumentParserContext context) throws IOException {
        Collection<IgnoredSourceFieldMapper.NameValue> ignoredFieldsMissingValues = context.getIgnoredFieldsMissingValues();
        if (ignoredFieldsMissingValues.isEmpty()) {
            return;
        }

        try (
            XContentParser parser = XContentHelper.createParser(
                parserConfiguration,
                context.sourceToParse().source(),
                context.sourceToParse().getXContentType()
            )
        ) {
            DocumentParserContext newContext = new RootDocumentParserContext(
                context.mappingLookup(),
                mappingParserContext,
                context.sourceToParse(),
                parser
            );
            var nameValues = parseDocForMissingValues(newContext, ignoredFieldsMissingValues);
            for (var nameValue : nameValues) {
                context.addIgnoredField(nameValue);
            }
        }
    }

/**
     * Simplified parsing version for retrieving the source of a given set of fields.
     */
    private static List<IgnoredSourceFieldMapper.NameValue> parseDocForMissingValues(
        DocumentParserContext context,
        Collection<IgnoredSourceFieldMapper.NameValue> ignoredFieldsMissingValues
    ) throws IOException {
        // Maps full name to the corresponding NameValue entry.
        Map<String, IgnoredSourceFieldMapper.NameValue> fields = new HashMap<>();
        for (var field : ignoredFieldsMissingValues) {
            fields.put(field.name(), field);
        }

        // Generate all possible parent names for the given fields.
        // This is used to skip processing objects that can't generate missing values.
        Set<String> parentNames = getPossibleParentNames(fields.keySet());
        List<IgnoredSourceFieldMapper.NameValue> result = new ArrayList<>();

        XContentParser parser = context.parser();
        XContentParser.Token currentToken = parser.nextToken();
        List<String> path = new ArrayList<>();
        String fieldName = null;
        while (currentToken != null) {
            while (currentToken != XContentParser.Token.FIELD_NAME) {
                if (fieldName != null
                    && (currentToken == XContentParser.Token.START_OBJECT || currentToken == XContentParser.Token.START_ARRAY)) {
                    if (parentNames.contains(getCurrentPath(path, fieldName)) == false) {
                        // No missing value under this parsing subtree, skip it.
                        parser.skipChildren();
                    } else {
                        path.add(fieldName);
                    }
                    fieldName = null;
                } else if (currentToken == XContentParser.Token.END_OBJECT || currentToken == XContentParser.Token.END_ARRAY) {
                    if (path.isEmpty() == false) {
                        path.removeLast();
                    }
                    fieldName = null;
                }
                currentToken = parser.nextToken();
                if (currentToken == null) {
                    return result;
                }
            }
            fieldName = parser.currentName();
            String fullName = getCurrentPath(path, fieldName);
            var leaf = fields.remove(fullName);
            if (leaf != null) {
                parser.nextToken();  // Advance the parser to the value to be read.
                result.add(leaf.cloneWithValue(XContentDataHelper.encodeToken(parser)));
            }
            if (fields.isEmpty()) {
                break;
            }
            currentToken = parser.nextToken();
        }
        return result;
    }

public void testObjectArrayAndValue() throws IOException {
        DocumentMapper documentMapper = createMapperService(syntheticSourceMapping(b -> {
            b.startObject("path");
            {
                b.field("type", "object");
                b.startObject("properties");
                {
                    b.startObject("stored");
                    {
                        b.field("type", "object").field("store_array_source", true);
                        b.startObject("properties").startObject("leaf").field("type", "integer").endObject().endObject();
                    }
                    b.endObject();
                }
                b.endObject();
            }
            b.endObject();
        })).documentMapper();
        // { "path": [ { "stored":[ { "leaf": 10 } ] }, { "stored": { "leaf": 20 } } ] }
        var syntheticSource = syntheticSource(documentMapper, b -> {
            b.startArray("path");
            {
                b.startObject();
                {
                    b.startArray("stored");
                    {
                        b.startObject().field("leaf", 10).endObject();
                    }
                    b.endArray();
                }
                b.endObject();
                b.startObject();
                {
                    b.startObject("stored").field("leaf", 20).endObject();
                }
                b.endObject();
            }
            b.endArray();
        });
        assertEquals("""
            {"path":[{"stored":[{"leaf":10}]},{"stored":{"leaf":20}}]}""", syntheticSource);
    }

private static Tuple<XContentParserConfiguration, XContentBuilder> cloneSubContextParserConfiguration(DocumentParserContext context)
        throws IOException {
        XContentParser parser = context.parser();
        XContentBuilder builder = XContentBuilder.builder(parser.contentType().xContent());
        builder.copyCurrentStructure(parser);

        XContentParserConfiguration configuration = XContentParserConfiguration.EMPTY.withRegistry(parser.getXContentRegistry())
            .withDeprecationHandler(parser.getDeprecationHandler())
            .withRestApiVersion(parser.getRestApiVersion());
        return Tuple.tuple(configuration, builder);
    }

/**
     * Generates all possible parent object names for the given full names.
     * For instance, for input ['path.to.foo', 'another.path.to.bar'], it returns:
     * [ 'path', 'path.to', 'another', 'another.path', 'another.path.to' ]
     */
    private static Set<String> getPossibleParentNames(Set<String> fullPaths) {
        if (fullPaths.isEmpty()) {
            return Collections.emptySet();
        }
        Set<String> paths = new HashSet<>();
        for (String fullPath : fullPaths) {
            String[] split = fullPath.split("\\.");
            if (split.length < 2) {
                continue;
            }
            StringBuilder builder = new StringBuilder(split[0]);
            paths.add(builder.toString());
            for (int i = 1; i < split.length - 1; i++) {
                builder.append(".");
                builder.append(split[i]);
                paths.add(builder.toString());
            }
        }
        return paths;
    }

private static String getCurrentPath(List<String> path, String fieldName) {
        assert fieldName != null;
        return path.isEmpty() ? fieldName : String.join(".", path) + "." + fieldName;
    }

/**
     * Clones the current context if this is the first array in the stack.
     * Records the information for retrieving and storing the array source if needed.
     * Applies to synthetic source only.
     */
    public final DocumentParserContext maybeCloneForArray(String leafName) throws IOException {
        if (canAddIgnoredField() && arrayFieldMissingValue == null) {
            DocumentParserContext subcontext = switchParser(parser());
            subcontext.arrayFieldMissingValue = IgnoredSourceFieldMapper.NameValue.fromContext(this, path().pathAsText(leafName), null);
            return subcontext;
        }
        return this;
    }

/**
     * Creates a sub-context from the current {@link DocumentParserContext} to indicate that the source for the sub-context has been
     * recorded and avoid duplicate recording for parts of the sub-context.
     */
    static DocumentParserContext cloneSubContextWithRecordedSource(DocumentParserContext context) throws IOException {
        DocumentParserContext subcontext = context.switchParser(context.parser());
        subcontext.setRecordedSource();  // Avoids double-storing parts of the source for the same parser subtree.
        return subcontext;
    }

/**
     * Stores the current parser structure (subtree) to an {@link XContentBuilder} and returns it, along with a
     * {@link DocumentParserContext} wrapping it that can be used to reparse the subtree.
     * The parser of the original context is also advanced to the end of the current structure (subtree) as a side effect.
     */
    static Tuple<DocumentParserContext, XContentBuilder> cloneSubContext(DocumentParserContext context) throws IOException {
        var tuple = cloneSubContextParserConfiguration(context);
        return Tuple.tuple(cloneDocumentParserContext(context, tuple.v1(), tuple.v2()), tuple.v2());
    }

private static DocumentParserContext cloneDocumentParserContext(
        DocumentParserContext context,
        XContentParserConfiguration configuration,
        XContentBuilder builder
    ) throws IOException {
        DocumentParserContext subcontext = context.switchParser(
            XContentHelper.createParserNotCompressed(configuration, BytesReference.bytes(builder), context.parser().contentType())
        );
        subcontext.setClonedSource();  // Avoids double-storing parts of the source for the same parser subtree.
        subcontext.parser().nextToken();
        return subcontext;
    }

